import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

public class DOMNodePointer_equals_TriageGen2Test {

    @Test
    public void testEquals_SameInstance() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);

        // Test the 'if (object == this)' branch
        assertTrue("An object should be equal to itself", pointer.equals(pointer));
    }

    @Test
    public void testEquals_NullObject() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);

        // Test the 'if (!(object instanceof DOMNodePointer))' branch with null
        assertFalse("Null should not be equal to the pointer", pointer.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);
        String differentObject = "not a DOMNodePointer";

        // Test the 'if (!(object instanceof DOMNodePointer))' branch with different class
        assertFalse("Different class should not be equal", pointer.equals(differentObject));
    }

    @Test
    public void testEquals_SameNode() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer1 = new DOMNodePointer(mockNode, Locale.ENGLISH);
        DOMNodePointer pointer2 = new DOMNodePointer(mockNode, Locale.ENGLISH);

        // Test the 'return node == other.node' branch (true case)
        assertTrue("Pointers with the same node should be equal", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_DifferentNode() {
        Node node1 = mock(Node.class);
        Node node2 = mock(Node.class);
        DOMNodePointer pointer1 = new DOMNodePointer(node1, Locale.ENGLISH);
        DOMNodePointer pointer2 = new DOMNodePointer(node2, Locale.ENGLISH);

        // Test the 'return node == other.node' branch (false case)
        assertFalse("Pointers with different nodes should not be equal", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_UsingConstructorWithId() {
        Node mockNode = mock(Node.class);
        DOMNodePointer pointer1 = new DOMNodePointer(mockNode, Locale.ENGLISH, "id1");
        DOMNodePointer pointer2 = new DOMNodePointer(mockNode, Locale.ENGLISH, "id2");

        // Ensure identity is based on the node, not the ID
        assertTrue("Equality should be based on the node instance", pointer1.equals(pointer2));
    }

    @Test
    public void testEquals_UsingParentConstructor() {
        Node parentNode = mock(Node.class);
        Node childNode = mock(Node.class);
        DOMNodePointer parentPointer = new DOMNodePointer(parentNode, Locale.ENGLISH);
        DOMNodePointer childPointer = new DOMNodePointer(parentPointer, childNode);

        DOMNodePointer anotherChildPointer = new DOMNodePointer(childNode, Locale.ENGLISH);

        // Test equality via the parent-based constructor path
        assertTrue("Child pointer should equal pointer created directly with same node", childPointer.equals(anotherChildPointer));
    }
}
